param([ValidateSet('Activate','Verify','Watch')][string]$Mode='Activate',[string]$App=(Join-Path $env:ProgramFiles 'LEAL INFO PDV'))
$ErrorActionPreference='Stop'
$env:PSModulePath=[IO.Path]::Combine($PSHOME,'Modules')+';'+[IO.Path]::Combine($env:SystemRoot,'System32/WindowsPowerShell/v1.0/Modules')
Import-Module ([IO.Path]::Combine($PSHOME,'Modules/Microsoft.PowerShell.Management/Microsoft.PowerShell.Management.psd1'))
Import-Module ([IO.Path]::Combine($PSHOME,'Modules/Microsoft.PowerShell.Utility/Microsoft.PowerShell.Utility.psd1'))
Import-Module ([IO.Path]::Combine($env:SystemRoot,'System32/WindowsPowerShell/v1.0/Modules/ScheduledTasks/ScheduledTasks.psd1'))
$App=[IO.Path]::GetFullPath($App).TrimEnd('\')
$admin=(New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
if(!$admin){
 if($Mode -ne 'Activate'){throw 'Administrator required'}
 $ps=[IO.Path]::Combine($env:SystemRoot,'System32/WindowsPowerShell/v1.0/powershell.exe')
 $p=Start-Process $ps -Verb RunAs -PassThru -ArgumentList ('-NoProfile -ExecutionPolicy Bypass -File "'+$PSCommandPath+'" -Mode Activate -App "'+$App+'"')
 $p.WaitForExit();exit $p.ExitCode
}
$fixture=$env:GITHUB_ACTIONS -eq 'true' -and (Test-Path (Join-Path $App 'QA-ISOLATED')) -and $App.StartsWith([IO.Path]::GetFullPath($env:RUNNER_TEMP),[StringComparison]::OrdinalIgnoreCase)
if($Mode -ne 'Watch' -and !$fixture -and !$App.StartsWith(([IO.Path]::GetFullPath($env:ProgramFiles).TrimEnd('\')+'\'),[StringComparison]::OrdinalIgnoreCase)){throw 'Unsupported installation path'}
$control=Join-Path $env:ProgramData 'LealInfoPDVProtection003'
$root=Join-Path $App '.pdv-update'
$task='LealInfoPDV-Protection003'
$names=@('LealInfoPDV.deps.json','LealInfoPDV.dll','LealInfoPDV.exe')
$expected=ConvertFrom-Json @'
{
  "LealInfoPDV.deps.json": "701aeea23b210fd71bb0a79a8ccaa2c72d7971710f5919a6b9b9d1e8921074c0",
  "LealInfoPDV.dll": "01fde106644a5832aa2aa5b189f0f32fd139dcf4034021417ba2def8d469bbc3",
  "LealInfoPDV.exe": "a0efa2d7a44465cddde526d96461d6998db2424599761343fcfeb2fdefd5d205"
}
'@
$workerBytes=[Convert]::FromBase64String('')
$workerHash='7f2bed9e19b4a0c8496e8f754d527dcb66c619cf36c1ef0aaf225a3bd3b9e3df'
function Hash([string]$path){$f=[IO.File]::OpenRead($path);$sha=[Security.Cryptography.SHA256]::Create();try{[BitConverter]::ToString($sha.ComputeHash($f)).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose();$f.Dispose()}}
function Flush([string]$path){$f=[IO.File]::Open($path,'Open','ReadWrite','None');try{$f.Flush($true)}finally{$f.Dispose()}}
function Save([string]$path,$value){$bytes=[Text.Encoding]::UTF8.GetBytes(($value|ConvertTo-Json -Depth 12));$tmp=$path+'.tmp';$f=[IO.File]::Open($tmp,'Create','Write','None');try{$f.Write($bytes,0,$bytes.Length);$f.Flush($true)}finally{$f.Dispose()};if(Test-Path $path){[IO.File]::Replace($tmp,$path,[NullString]::Value)}else{[IO.File]::Move($tmp,$path)}}
function Match([string]$folder){foreach($n in $names){if(!(Test-Path (Join-Path $folder $n)) -or (Hash (Join-Path $folder $n)) -ne $expected.$n){return $false}};return $true}
function Secure([string]$folder){
 New-Item -ItemType Directory $folder -Force|Out-Null
 if(([IO.File]::GetAttributes($folder) -band [IO.FileAttributes]::ReparsePoint) -ne 0){throw 'Reparse directory refused'}
 if(@(Get-ChildItem $folder -Force -Recurse|Where-Object{($_.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0}).Count){throw 'Reparse member refused'}
 $acl=New-Object Security.AccessControl.DirectorySecurity;$acl.SetAccessRuleProtection($true,$false)
 foreach($sid in @('S-1-5-18','S-1-5-32-544')){$id=New-Object Security.Principal.SecurityIdentifier $sid;$acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($id,'FullControl','ContainerInherit,ObjectInherit','None','Allow')))}
 $users=New-Object Security.Principal.SecurityIdentifier 'S-1-5-32-545';$acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($users,'ReadAndExecute','ContainerInherit,ObjectInherit','None','Allow')))
 $acl.SetOwner((New-Object Security.Principal.SecurityIdentifier 'S-1-5-32-544'));(Get-Item $folder).SetAccessControl($acl)
}
function VerifyProtection{
 $cfg=Get-Content (Join-Path $control 'protection.json') -Raw|ConvertFrom-Json
 if($cfg.App -ne $App -or $cfg.Channel -ne '003' -or $cfg.InstalledVersion -ne '10.415'){throw 'Wrong protection identity'}
 if((Hash (Join-Path $control 'watcher.ps1')) -ne $cfg.WatcherSha256 -or (Hash (Join-Path $control 'worker.ps1')) -ne $workerHash){throw 'Recovery code integrity failed'}
 if(!(Match (Join-Path $root 'previous'))){throw 'Backup SHA-256 verification failed'}
 $registered=Get-ScheduledTask -TaskName $task
 if($registered.Principal.UserId -notin @('SYSTEM','S-1-5-18')){throw 'Recovery task is not SYSTEM'}
 if($registered.State -eq 'Disabled' -or $registered.Actions.Execute -ne (Join-Path $env:SystemRoot 'System32/WindowsPowerShell/v1.0/powershell.exe')){throw 'Recovery task unavailable'}
 if($registered.Actions.Arguments -ne $cfg.TaskArguments){throw 'Recovery action mismatch'}
 return $cfg
}
function Arm{
 Save (Join-Path $root 'journal.json') ([ordered]@{App=$App;Channel='003';Version='10.415';Phase='Armed';Previous=$expected;Target=$expected;Nonce=[Guid]::NewGuid().ToString('N');Activation='Protection003-NoUpdate';CreatedUtc=[DateTime]::UtcNow.ToString('o')})
}
try{
 if($Mode -eq 'Activate'){
  if(!(Match $App)){throw 'Files are not the approved client 003 version 10.415. Nothing replaced.'}
  if(Test-Path (Join-Path $control 'protection.json')){$null=VerifyProtection;Write-Output 'PASS - PROTECAO 003 JA ATIVA; 10.415 PRESERVADA';exit 0}
  if((Test-Path $root) -and @(Get-ChildItem $root -Force).Count){throw 'Existing recovery state found. Activation stopped without overwriting it.'}
  if((Test-Path $control) -and @(Get-ChildItem $control -Force).Count){throw 'Existing external protection found. Nothing overwritten.'}
  if(Get-ScheduledTask -TaskName $task -ErrorAction SilentlyContinue){throw 'Existing unrelated recovery task; nothing changed'}
  Secure $control;Secure $root
  $gate=[IO.File]::Open((Join-Path $root 'transaction.lock'),'OpenOrCreate','ReadWrite','None')
  try{
   New-Item -ItemType Directory (Join-Path $root 'previous') -Force|Out-Null
   foreach($n in $names){$dest=Join-Path $root ('previous/'+$n);[IO.File]::Copy((Join-Path $App $n),$dest,$false);Flush $dest}
   if(!(Match (Join-Path $root 'previous')) -or !(Match $App)){throw 'Backup integrity failed; no application file changed'}
   [IO.File]::WriteAllBytes((Join-Path $control 'worker.ps1'),$workerBytes);Flush (Join-Path $control 'worker.ps1')
   if((Hash (Join-Path $control 'worker.ps1')) -ne $workerHash){throw 'Embedded validated worker hash mismatch'}
   [IO.File]::Copy($PSCommandPath,(Join-Path $control 'watcher.ps1'),$false);Flush (Join-Path $control 'watcher.ps1')
   $guard=Join-Path $root 'startup.guard';$f=[IO.File]::Open($guard,'CreateNew','Write','None');try{$f.Flush($true)}finally{$f.Dispose()}
   Arm
   $ps=Join-Path $env:SystemRoot 'System32/WindowsPowerShell/v1.0/powershell.exe'
   $arguments='-NoProfile -ExecutionPolicy Bypass -File "'+(Join-Path $control 'watcher.ps1')+'" -Mode Watch -App "'+$App+'"'
   $action=New-ScheduledTaskAction -Execute $ps -Argument $arguments
   $boot=New-ScheduledTaskTrigger -AtStartup
   $retry=New-ScheduledTaskTrigger -Once -At (Get-Date).AddMinutes(1) -RepetitionInterval (New-TimeSpan -Minutes 1)
   $settings=New-ScheduledTaskSettingsSet -StartWhenAvailable -MultipleInstances IgnoreNew -ExecutionTimeLimit (New-TimeSpan -Minutes 5)
   Register-ScheduledTask -TaskName $task -Action $action -Trigger @($boot,$retry) -Settings $settings -User 'S-1-5-18' -RunLevel Highest -Force|Out-Null
   Save (Join-Path $control 'protection.json') ([ordered]@{Channel='003';InstalledVersion='10.415';App=$App;WatcherSha256=(Hash (Join-Path $control 'watcher.ps1'));TaskArguments=$arguments;WorkerSource='029efff14772e91b12b3a72aa01bb61b2120d1b1';UpdateAuthorized=$false})
   $null=VerifyProtection
  }finally{$gate.Dispose()}
  if(!(Match $App)){throw 'Installed integrity changed; recovery task retained'}
  Write-Output 'PASS - PROTECAO EXTERNA 003 ATIVA; BACKUP SHA-256 OK; 10.415 PRESERVADA; ATUALIZACAO CONTINUA BLOQUEADA'
 }elseif($Mode -eq 'Verify'){
  $null=VerifyProtection
  if(!(Match $App)){throw 'Recovery pending; installed set differs from approved 10.415'}
  Write-Output 'PASS - PROTECAO 003 E BACKUP VERIFICADOS; 10.415 INTACTA'
 }else{
  $null=VerifyProtection
  if(Match $App){exit 0}
  # Never compete with a live sale or legacy copy process. Retry automatically when they stop.
  foreach($p in @(Get-Process LealInfoPDV -ErrorAction SilentlyContinue)){if(!$p.Path -or $p.Path -eq (Join-Path $App 'LealInfoPDV.exe')){exit 0}}
  foreach($row in @(Get-CimInstance Win32_Process -Filter "Name='powershell.exe'")){
   $line=[string]$row.CommandLine
   $m=[regex]::Match($line,'-File\s+"([^"]*apply-update\.ps1)"',[Text.RegularExpressions.RegexOptions]::IgnoreCase)
   if($m.Success -and (Test-Path $m.Groups[1].Value)){$text=[IO.File]::ReadAllText($m.Groups[1].Value);$needle='$app=' + "'" + $App.Replace("'","''") + "'";if($text.Contains($needle)){exit 0}}
  }
  # The existing tested engine owns its transaction lock and restores only the three approved files.
  $j=Get-Content (Join-Path $root 'journal.json') -Raw|ConvertFrom-Json
  if($j.Activation -ne 'Protection003-NoUpdate' -or $j.App -ne $App){throw 'Foreign journal; no recovery performed'}
  & (Join-Path $env:SystemRoot 'System32/WindowsPowerShell/v1.0/powershell.exe') -NoProfile -ExecutionPolicy Bypass -File (Join-Path $control 'worker.ps1') -Mode Recover -App $App -Channel '003'
  if($LASTEXITCODE -ne 0 -or !(Match $App)){throw 'Recovery incomplete; backup retained; automatic retry remains enabled'}
  Arm
  Save (Join-Path $control 'last-recovery.json') @{Channel='003';RestoredVersion='10.415';Sha256Verified=$true;Utc=[DateTime]::UtcNow.ToString('o')}
 }
}catch{Write-Error $_;exit 1}
